const UDP_PORT_VALUES: &[u16] = &[
    69, 80, 123, 137, 161, 162, 443, 514, 520, 546, 547, 1645, 1646, 1812, 1813, 1985, 2055, 3784,
    3785, 4739, 4784, 5060, 5061, 6343, 9995, 9996, 51820,
];

static UDP_PORT_CLAIMED: [u64; 810] = port_bits(UDP_PORT_VALUES);

// Out of line: almost no traffic claims a layer here, so the match
// must not weigh on the callers that never reach it.
#[inline(never)]
fn by_udp_port_one(v: u16, payload: &[u8]) -> Option<ProtoId> {
    match v {
        69 => Some(ProtoId::Tftp),
        80 | 443 => crate::layers::quic::looks_like(payload).then_some(ProtoId::Quic),
        123 => Some(ProtoId::Ntp),
        137 => Some(ProtoId::Nbns),
        161 | 162 => Some(ProtoId::Snmp),
        514 => Some(ProtoId::Syslog),
        520 => Some(ProtoId::Rip),
        546 | 547 => Some(ProtoId::Dhcp6),
        1645 | 1646 | 1812 | 1813 => Some(ProtoId::Radius),
        1985 => Some(ProtoId::Hsrp),
        2055 | 9995 | 9996 => {
            if crate::layers::ipfix::looks_like(payload) {
                return Some(ProtoId::Ipfix);
            }
            if crate::layers::netflow5::looks_like(payload) {
                return Some(ProtoId::NetflowV5);
            }
            if crate::layers::netflow9::looks_like(payload) {
                return Some(ProtoId::NetflowV9);
            }
            None
        }
        3784 | 3785 | 4784 => Some(ProtoId::Bfd),
        4739 => crate::layers::ipfix::looks_like(payload).then_some(ProtoId::Ipfix),
        5060 | 5061 => crate::layers::sip::looks_like(payload).then_some(ProtoId::Sip),
        6343 => Some(ProtoId::SFlow),
        51820 => Some(ProtoId::WireGuard),
        _ => None,
    }
}

/// The destination port names the service, so it is asked first.
#[inline]
pub fn by_udp_port(sport: u16, dport: u16, payload: &[u8]) -> Option<ProtoId> {
    if !claimed(&UDP_PORT_CLAIMED, dport) && !claimed(&UDP_PORT_CLAIMED, sport) {
        return None;
    }
    by_udp_port_one(dport, payload).or_else(|| by_udp_port_one(sport, payload))
}

